SELECT a.id, a.issue_id, a.user_id, a.action, a.field_name, , a.created_at, u.display_name AS user_name, i.issue_key, i.title AS issue_title FROM issue_activity a LEFT JOIN sys_user u ON u.id = a.user_id LEFT JOIN issue i ON i.id = a.issue_id WHERE a.issue_id IN
#{id}
ORDER BY a.created_at DESC LIMIT #{limit}

SELECT a.id, a.issue_id, a.user_id, a.action, a.field_name, , a.created_at, u.display_name AS user_name, i.issue_key, i.title AS issue_title FROM issue_activity a INNER JOIN issue i ON i.id = a.issue_id AND i.deleted_at IS NULL LEFT JOIN sys_user u ON u.id = a.user_id WHERE i.project_id IN
#{pid}
ORDER BY a.created_at DESC LIMIT #{limit}

SELECT id FROM issue
WHERE project_id = #{projectId}
  AND deleted_at IS NOT NULL
  AND deleted_at < #{cutoff}
